
namespace TheEngine.ECS;

public static partial class EntityExtensions
{
private static IChunkDataIterator? cachedItr;

        public static void ForEach<N0>(this Archetype archetype, 
            Action<IChunkDataIterator, int, int, int, ManagedComponentDataAccess<N0>> process)where N0 : IManagedComponentData
        {
            var entityManager = archetype.EntityManager;
            var iterator = entityManager.ArchetypeIterator(archetype);
            while (iterator.MoveNext())
            {
                cachedItr = iterator.Current;
                    process(cachedItr, 0, 0, cachedItr.Length,
cachedItr.ManagedDataAccess<N0>()
                    );
            }
        }

        public static void ForEachState<S, N0>(this Archetype archetype, S state, 
            Action<S, IChunkDataIterator, int, int, int, ManagedComponentDataAccess<N0>> process)where N0 : IManagedComponentData
        {
            var entityManager = archetype.EntityManager;
            var iterator = entityManager.ArchetypeIterator(archetype);
            while (iterator.MoveNext())
            {
                cachedItr = iterator.Current;
                    process(state, cachedItr, 0, 0, cachedItr.Length,
cachedItr.ManagedDataAccess<N0>()
                    );
            }
        }

        public static void ParallelForEach<N0>(this Archetype archetype, 
            Action<IChunkDataIterator, int, int, int, ManagedComponentDataAccess<N0>> process)where N0 : IManagedComponentData
        {
            var entityManager = archetype.EntityManager;
            var iterator = entityManager.ArchetypeIterator(archetype);
            while (iterator.MoveNext())
            {
                cachedItr = iterator.Current;
                    RunThreads(0, cachedItr.Length, process, null, (process, state, thread, s, e) => ((Action<IChunkDataIterator, int, int, int, ManagedComponentDataAccess<N0>>)process!)(cachedItr, thread, s, e,
cachedItr.ManagedDataAccess<N0>()
));
            }
        }

